using System.Reflection;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class SuppressSourceGenerationAnalyzerTests(ITestOutputHelper logger)
{
    private static ImmutableArray<DiagnosticAnalyzer> LoadAnalyzers()
    {
        Assembly asm = typeof(MessagePack.SourceGenerator.MessagePackGenerator).Assembly;
        return asm.GetTypes()
            .Where(t => !t.IsAbstract && typeof(DiagnosticAnalyzer).IsAssignableFrom(t) && t.GetCustomAttributes(typeof(DiagnosticAnalyzerAttribute), false).Length > 0)
            .Select(t => (DiagnosticAnalyzer)Activator.CreateInstance(t)!)
            .ToImmutableArray();
    }

    private async Task<ImmutableArray<Diagnostic>> GetAnalyzerDiagnosticsAsync(string source)
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = framework.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();
        SyntaxTree tree = CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest));
        CSharpCompilation compilation = CSharpCompilation.Create("ReceiptsTestAssembly", new[] { tree }, references, new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        ImmutableArray<Diagnostic> diagnostics = await compilation.WithAnalyzers(LoadAnalyzers()).GetAnalyzerDiagnosticsAsync();
        foreach (Diagnostic d in diagnostics)
        {
            logger.WriteLine(d.ToString());
        }

        return diagnostics;
    }

    [Fact]
    public async Task DuplicateIntKeyProperties_StillReportsDiagnosticsWithoutAnalyzerCrash()
    {
        string source = """
            using MessagePack;

            namespace Repro;

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class DuplicateIntKeys
            {
                [Key(0)]
                public int A { get; set; }

                [Key(0)]
                public int B { get; set; }

                public int Unattributed { get; set; }
            }
            """;
        ImmutableArray<Diagnostic> diagnostics = await this.GetAnalyzerDiagnosticsAsync(source);
        Assert.DoesNotContain(diagnostics, d => d.Id == "AD0001");
        Assert.Contains(diagnostics, d => d.Id == "MsgPack004");
    }

    [Fact]
    public async Task DuplicateStringKeyProperties_StillReportsDiagnosticsWithoutAnalyzerCrash()
    {
        string source = """
            using MessagePack;

            namespace Repro;

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class DuplicateStringKeys
            {
                [Key("a")]
                public int A { get; set; }

                [Key("a")]
                public int B { get; set; }

                public int Unattributed { get; set; }
            }
            """;
        ImmutableArray<Diagnostic> diagnostics = await this.GetAnalyzerDiagnosticsAsync(source);
        Assert.DoesNotContain(diagnostics, d => d.Id == "AD0001");
        Assert.Contains(diagnostics, d => d.Id == "MsgPack004");
    }
}

